import{_ as p,a0 as o,w as d,s as r,I as i,x as a,a1 as t,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"面向系統管理員的 Bash 指南 | LCTT x X-CMD","titleTemplate":false,"description":"面向系統管理員的 Bash 指南 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"面向系統管理員的 Bash 指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"面向系統管理員的 Bash 指南 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180731 A sysadmin-s guide to Bash","title":"面向系統管理員的 Bash 指南","tag":"201808","desc":""},"relativePath":"201808/20180731 A sysadmin-s guide to Bash.md","filePath":"[post].md"}'),h={name:"201808/20180731 A sysadmin-s guide to Bash.md"};function u(g,s,b,k,c,f){const e=o("Link");return d(),r("div",null,[s[34]||(s[34]=i("h1",{id:"面向系統管理員的-bash-指南",tabindex:"-1"},[a("面向系統管理員的 Bash 指南 "),i("a",{class:"header-anchor",href:"#面向系統管理員的-bash-指南","aria-label":"Permalink to “面向系統管理員的 Bash 指南”"},"​")],-1)),s[35]||(s[35]=i("blockquote",null,[i("p",null,"使 Bash 工作的更好的技巧。")],-1)),s[36]||(s[36]=i("p",null,[i("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/build_structure_tech_program_code_construction.png?itok=nVsiLuag",alt:""})],-1)),i("p",null,[s[1]||(s[1]=a("每個行業都有一個該行業的大師們最常使用的工具。 對於許多系統管理員來説，這個工具就是他們的 ",-1)),t(e,{href:"http://www.catb.org/jargon/html/S/shell.html"},{default:n(()=>[...s[0]||(s[0]=[a("shell",-1)])]),_:1}),s[2]||(s[2]=a("。 在大多數 Linux 和其他類 Unix 系統上，默認的 shell 是 Bash。",-1))]),s[37]||(s[37]=l(`<p>Bash 是一個相當古老的程序——它起源於 20 世紀 80 年代後期——但它建立在更多更老的 shell 上，比如 C shell（csh），csh 至少是它 10 年前的前輩了。 因為 shell 的概念是那麼古老，所以有大量的神秘知識等待着系統管理員去吸收領悟，使其生活更輕鬆。</p><p>我們來看看一些基礎知識。</p><p>在某些時候，誰曾經無意中以 root 身份運行命令並導致某種問題？ <em>舉手</em></p><p>我很確定我們很多人一度都是那個人。 這很痛苦。 這裏有一些非常簡單的技巧可以防止你再次碰上這類問題。</p><h3 id="使用別名" tabindex="-1">使用別名 <a class="header-anchor" href="#使用別名" aria-label="Permalink to “使用別名”">​</a></h3><p>首先，為 <code>mv</code> 和 <code>rm</code> 等命令設置別名，指向 <code>mv -i</code> 和 <code>rm -i</code>。 這將確保在運行 <code>rm -f /boot</code> 時至少需要你確認。 在 Red Hat 企業版 Linux 中，如果你使用 root 帳户，則默認設置這些別名。</p><p>如果你還要為普通用户帳户設置這些別名，只需將這兩行放入家目錄下名為 <code>.bashrc</code> 的文件中（這些也適用於 <code>sudo</code> ）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias mv=&#39;mv -i&#39;</span></span>
<span class="line"><span>alias rm=&#39;rm -i&#39;</span></span></code></pre></div><h3 id="讓你的-root-提示符脱穎而出" tabindex="-1">讓你的 root 提示符脱穎而出 <a class="header-anchor" href="#讓你的-root-提示符脱穎而出" aria-label="Permalink to “讓你的 root 提示符脱穎而出”">​</a></h3><p>你可以採取的防止意外發生的另一項措施是確保你很清楚在使用 root 帳户。 在日常工作中，我通常會讓 root 提示符從日常使用的提示符中脱穎而出。</p><p>如果將以下內容放入 root 的家目錄中的 <code>.bashrc</code> 文件中，你將看到一個黑色背景上的紅色的 root 提示符，清楚地表明你（或其他任何人）應該謹慎行事。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export PS1=&quot;\\[$(tput bold)$(tput setab 0)$(tput setaf 1)\\]\\u@\\h:\\w # \\[$(tput sgr0)\\]&quot;</span></span></code></pre></div><p>實際上，你應該儘可能避免以 root 用户身份登錄，而是通過 <code>sudo</code> 運行大多數系統管理命令，但這是另一回事。</p><p>使用了一些小技巧用於防止使用 root 帳户時的“不小心的副作用”之後，讓我們看看 Bash 可以幫助你在日常工作中做的一些好事。</p><h3 id="控制你的歷史" tabindex="-1">控制你的歷史 <a class="header-anchor" href="#控制你的歷史" aria-label="Permalink to “控制你的歷史”">​</a></h3><p>你可能知道在 Bash 中你按向上的箭頭時能看見和重新使用你之前所有（好吧，大多數）的命令。這是因為這些命令已經保存到了你家目錄下的名為 <code>.bash_history</code> 的文件中。這個歷史文件附帶了一組有用的設置和命令。</p><p>首先，你可以通過鍵入 <code>history</code> 來查看整個最近的命令歷史記錄，或者你可以通過鍵入 <code>history 30</code> 將其限制為最近 30 個命令。不過這技巧太平淡無奇了（LCTT 譯註： vanilla 原為香草，後引申沒拓展的、標準、普通的，比如 vanilla C++ compiler 意為標準 C++ 編譯器）。 你可以更好地控制 Bash 保存的內容以及保存方式。</p><p>例如，如果將以下內容添加到 <code>.bashrc</code>，那麼任何以空格開頭的命令都不會保存到歷史記錄列表中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HISTCONTROL=ignorespace</span></span></code></pre></div><p>如果你需要以明文形式將密碼傳遞給一個命令，這就非常有用。 （是的，這太可怕了，但它仍然會發生。）</p><p>如果你不希望經常執行的命令充斥在歷史記錄中，請使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HISTCONTROL=ignorespace:erasedups</span></span></code></pre></div><p>這樣，每次使用一個命令時，都會從歷史記錄文件中刪除之前出現的所有相同命令，並且只將最後一次調用保存到歷史記錄列表中。</p><p>我特別喜歡的歷史記錄設置是 <code>HISTTIMEFORMAT</code> 設置。 這將在歷史記錄文件中在所有的條目前面添加上時間戳。 例如，我使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HISTTIMEFORMAT=&quot;%F %T  &quot;</span></span></code></pre></div><p>當我輸入 <code>history 5</code> 時，我得到了很好的完整信息，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1009  2018-06-11 22:34:38  cat /etc/hosts</span></span>
<span class="line"><span>1010  2018-06-11 22:34:40  echo $foo</span></span>
<span class="line"><span>1011  2018-06-11 22:34:42  echo $bar</span></span>
<span class="line"><span>1012  2018-06-11 22:34:44  ssh myhost</span></span>
<span class="line"><span>1013  2018-06-11 22:34:55  vim .bashrc</span></span></code></pre></div><p>這使我更容易瀏覽我的命令歷史記錄並找到我兩天前用來建立到我家實驗室的 SSH 連接（我一次又一次地忘記......）。</p><h3 id="bash-最佳實踐" tabindex="-1">Bash 最佳實踐 <a class="header-anchor" href="#bash-最佳實踐" aria-label="Permalink to “Bash 最佳實踐”">​</a></h3><p>我將在編寫 Bash 腳本時最好的（或者至少是好的，我不要求無所不知）11 項實踐列出來。</p><p>11、 Bash 腳本可能變得複雜，不過註釋也很方便。 如果你在考慮是否要添加註釋，那就添加一個註釋。 如果你在週末之後回來並且不得不花時間搞清楚你上週五想要做什麼，那你是忘了添加註釋。</p><p>10、 用花括號括起所有變量名，比如 <code>\${myvariable}</code>。 養成這個習慣可以使用 <code>\${variable}_suffix</code> 這種用法了，還能提高整個腳本的一致性。</p><p>9、 計算表達式時不要使用反引號；請改用 <code>$()</code> 語法。 所以使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for  file in $(ls); do</span></span></code></pre></div><p>而不使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for  file in \`ls\`; do</span></span></code></pre></div><p>前一個方式是可嵌套的，更易於閲讀的，還能讓一般的系統管理員羣體感到滿意。 不要使用反引號。</p><p>8、 一致性是好的。 選擇一種風格並在整個腳本中堅持下去。 顯然，我喜歡人們選擇 <code>$()</code> 語法而不是反引號，並將其變量包在花括號中。 我更喜歡人們使用兩個或四個空格而不是製表符來縮進，但即使你選擇了錯誤的方式，也要一貫地錯下去。</p>`,38)),i("p",null,[s[5]||(s[5]=a("7、 為 Bash 腳本使用適當的",-1)),i("ruby",null,[t(e,{href:"https://linux.cn/article-3664-1.html"},{default:n(()=>[...s[3]||(s[3]=[a("釋伴",-1)])]),_:1}),s[4]||(s[4]=i("rt",null,"shebang",-1))]),s[6]||(s[6]=a("（LCTT 譯註：",-1)),s[7]||(s[7]=i("strong",null,"Shebang",-1)),s[8]||(s[8]=a("，也稱為 ",-1)),s[9]||(s[9]=i("strong",null,"Hashbang",-1)),s[10]||(s[10]=a(" ，是一個由井號和歎號構成的字符序列 ",-1)),s[11]||(s[11]=i("code",null,"#!",-1)),s[12]||(s[12]=a(" ，其出現在文本文件的第一行的前兩個字符。 在文件中存在釋伴的情況下，類 Unix 操作系統的程序載入器會分析釋伴後的內容，將這些內容作為解釋器指令，並調用該指令，並將載有釋伴的文件路徑作為該解釋器的參數）。 因為我正在編寫Bash腳本，只打算用 Bash 執行它們，所以我經常使用 ",-1)),s[13]||(s[13]=i("code",null,"#!/usr/bin/bash",-1)),s[14]||(s[14]=a(" 作為我的釋伴。 不要使用 ",-1)),s[15]||(s[15]=i("code",null,"#!/bin/sh",-1)),s[16]||(s[16]=a(" 或 ",-1)),s[17]||(s[17]=i("code",null,"#!/usr/bin/sh",-1)),s[18]||(s[18]=a("。 你的腳本會被執行，但它會以兼容模式運行——可能會產生許多意外的副作用。 （當然，除非你想要兼容模式。）",-1))]),s[38]||(s[38]=l(`<p>6、 比較字符串時，在 <code>if</code> 語句中給變量加上引號是個好主意，因為如果你的變量是空的，Bash 會為這樣的行拋出一個錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ \${myvar} == &quot;foo&quot; ]; then</span></span>
<span class="line"><span>  echo &quot;bar&quot;</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>對於這樣的行，將判定為 <code>false</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ &quot;\${myvar}&quot; == &quot;foo&quot; ]; then</span></span>
<span class="line"><span>  echo &quot;bar&quot;</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>此外，如果你不確定變量的內容（例如，在解析用户輸入時），請給變量加引號以防止解釋某些特殊字符，並確保該變量被視為單個單詞，即使它包含空格。</p><p>5、 我想這是一個品味問題，但我更喜歡使用雙等號（ <code>==</code> ），即使是比較 Bash 中的字符串。 這是一致性的問題，儘管對於字符串比較，只有一個等號會起作用，我的思維立即變為“單個 <code>=</code> 是一個賦值運算符！”</p><p>4、 使用適當的退出代碼。 確保如果你的腳本無法執行某些操作，則會向用户顯示已寫好的失敗消息（最好提供解決問題的方法）併發送非零退出代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># we have failed</span></span>
<span class="line"><span>echo &quot;Process has failed to complete, you need to manually restart the whatchamacallit&quot;</span></span>
<span class="line"><span>exit 1</span></span></code></pre></div><p>這樣可以更容易地以編程方式從另一個腳本調用你的腳本並驗證其成功完成。</p><p>3、 使用 Bash 的內置機制為變量提供合理的默認值，或者如果未定義你希望定義的變量，則拋出錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># this sets the value of $myvar to redhat, and prints &#39;redhat&#39;</span></span>
<span class="line"><span>echo \${myvar:=redhat}</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># this throws an error reading &#39;The variable myvar is undefined, dear reader&#39; if $myvar is undefined</span></span>
<span class="line"><span>\${myvar:?The variable myvar is undefined, dear reader}</span></span></code></pre></div><p>2、 特別是如果你正在編寫大型腳本，或者是如果你與其他人一起開發該大型腳本，請考慮在函數內部定義變量時使用 <code>local</code> 關鍵字。 <code>local</code> 關鍵字將創建一個局部變量，該變量只在該函數中可見。 這限制了變量衝突的可能性。</p><p>1、 每個系統管理員有時必須這樣做：在控制台上調試一些東西，可能是數據中心的真實服務器，也可能是虛擬化平台的虛擬服務器。 如果你必須以這種方式調試腳本，你會感謝你自己記住了這個：不要讓你的腳本中的行太長！</p><p>在許多系統上，控制台的默認寬度仍為 80 個字符。 如果你需要在控制台上調試腳本並且該腳本有很長的行，那麼你將成為一個悲傷的熊貓。 此外，具有較短行的腳本—— 默認值仍為 80 個字符——在普通編輯器中也更容易閲讀和理解！</p><p>我真的很喜歡 Bash。 我可以花幾個小時寫這篇文章或與其他愛好者交流優秀的技巧。 就希望你們能在評論中留下讚美。</p><hr>`,17)),i("p",null,[s[20]||(s[20]=a("via: ",-1)),t(e,{href:"https://opensource.com/article/18/7/admin-guide-bash"},{default:n(()=>[...s[19]||(s[19]=[a("https://opensource.com/article/18/7/admin-guide-bash",-1)])]),_:1})]),i("p",null,[s[25]||(s[25]=a("作者：",-1)),t(e,{href:"https://opensource.com/users/wzzrd"},{default:n(()=>[...s[21]||(s[21]=[a("Maxim Burgerhout",-1)])]),_:1}),s[26]||(s[26]=a(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[22]||(s[22]=[a("lujun9972",-1)])]),_:1}),s[27]||(s[27]=a(" 譯者：",-1)),t(e,{href:"https://github.com/Flowsnow"},{default:n(()=>[...s[23]||(s[23]=[a("Flowsnow",-1)])]),_:1}),s[28]||(s[28]=a(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[24]||(s[24]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[31]||(s[31]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[29]||(s[29]=[a("LCTT",-1)])]),_:1}),s[32]||(s[32]=a(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...s[30]||(s[30]=[a("Linux中國",-1)])]),_:1}),s[33]||(s[33]=a(" 榮譽推出",-1))])])}const C=p(h,[["render",u]]);export{v as __pageData,C as default};
